widget_def.init:
var root=container;
root.innerHTML='<div style="background:#0d0f14;font-family:system-ui,sans-serif;padding:12px;color:#e5e7eb;display:flex;flex-direction:column;gap:10px">'
+'<div style="font-weight:700;font-size:13px">🧪 Ionisation — Henderson-Hasselbalch</div>'
+'<div style="background:#111827;border:1px solid rgba(58,176,158,.25);border-radius:8px;padding:10px">'
+'<div style="font-size:10px;color:#9ca3af;text-transform:uppercase">Type <span id="hh-type" style="color:#3ab09e">Acide</span></div>'
+'<button id="hh-tog" style="margin:4px 0;padding:4px 10px;border-radius:6px;border:1px solid rgba(255,255,255,.15);background:#1f2937;color:#e5e7eb;font-size:11px;cursor:pointer">Basculer acide/base</button>'
+'<div style="font-size:10px;color:#9ca3af;text-transform:uppercase;margin-top:6px">pKa <span id="hh-pka-l" style="color:#3ab09e">9.9</span></div>'
+'<input type="range" id="hh-pka" min="0" max="14" value="9.9" step="0.1" style="width:100%;accent-color:#3ab09e">'
+'<div style="font-size:10px;color:#9ca3af;text-transform:uppercase;margin-top:6px">pH du milieu <span id="hh-ph-l" style="color:#3ab09e">7.4</span></div>'
+'<input type="range" id="hh-ph" min="0" max="14" value="7.4" step="0.1" style="width:100%;accent-color:#3ab09e">'
+'<div style="text-align:center;margin:8px 0"><span id="hh-ion" style="font-size:28px;font-weight:800;color:#3ab09e">–</span> <span style="color:#9ca3af;font-size:12px">% ionisé</span></div>'
+'<div id="hh-bar" style="height:18px;border-radius:9px;overflow:hidden;display:flex;background:#1f2937"><div id="hh-bi" style="background:#60a5fa;height:100%"></div><div id="hh-bn" style="background:#fbbf24;height:100%"></div></div>'
+'<div style="display:flex;justify-content:space-between;font-size:9px;color:#9ca3af;margin-top:3px"><span>🔵 ionisé (hydrosoluble)</span><span>🟡 non-ionisé (lipophile)</span></div>'
+'<div id="hh-note" style="font-size:10px;color:#9ca3af;margin-top:8px;line-height:1.5"></div>'
+'<div style="font-size:9px;color:#6b7280;margin-top:6px">Acide : %ion = 100/(1+10^(pKa−pH)) · Base : 100/(1+10^(pH−pKa)). Seule la forme non-ionisée franchit les membranes.</div>'
+'</div></div>';
var isAcid=true;
function calc(){
  var pka=+root.querySelector('#hh-pka').value, ph=+root.querySelector('#hh-ph').value;
  root.querySelector('#hh-pka-l').textContent=pka.toFixed(1);
  root.querySelector('#hh-ph-l').textContent=ph.toFixed(1);
  var ion = isAcid ? 100/(1+Math.pow(10,pka-ph)) : 100/(1+Math.pow(10,ph-pka));
  root.querySelector('#hh-ion').textContent=ion.toFixed(1);
  root.querySelector('#hh-bi').style.width=ion+'%';
  root.querySelector('#hh-bn').style.width=(100-ion)+'%';
  var n=root.querySelector('#hh-note');
  if(100-ion>50) n.textContent='Forme non-ionisée majoritaire → bonne absorption membranaire / réabsorption tubulaire.';
  else n.textContent='Forme ionisée majoritaire → faible passage membranaire, favorise élimination urinaire (piégeage ionique).';
}
root.querySelector('#hh-tog').addEventListener('click',function(){isAcid=!isAcid;root.querySelector('#hh-type').textContent=isAcid?'Acide':'Base';calc();});
root.querySelector('#hh-pka').addEventListener('input',calc);
root.querySelector('#hh-ph').addEventListener('input',calc);
calc();
